import json, re

idx = open('/work/workspace/library/INDEX.md').read()
data = json.load(open('/work/workspace/deliverable/citations.json'))

rows = {}
for line in idx.splitlines():
    m = re.match(r'^\|\s*`([^`]+)`\s*\|\s*(.*?)\s*\|\s*(.*?)\s*\|\s*(.*?)\s*\|\s*$', line)
    if m:
        rows[m.group(1)] = m

print("INDEX rows parsed:", len(rows))
print("citation entries:", len(data))

citable = {k for k in rows if not k.startswith('memo_bank/')}
print("citable INDEX files:", len(citable))

errors = []
matched = set()
for e in data:
    f = e['library_file']
    if f not in rows:
        errors.append(f"{f} not in INDEX")
        continue
    matched.add(f)
    g = [rows[f].group(i) for i in (2, 3, 4)]
    status_cell = next((c for c in g if re.search(r'in force|superseded|vacated|modified', c)), None)
    if status_cell is None:
        errors.append(f"{f}: no status column found")
    elif e['status_checked'] != status_cell:
        errors.append(f"{f}: json={e['status_checked']!r} index={status_cell!r}")

print("INDEX citable rows missing from json:", sorted(citable - matched))
print("json rows flagged memo_bank:", sorted(matched - citable))
print("ERRORS:", errors if errors else "none")

statuses = {}
for e in data:
    statuses[e['status_checked']] = statuses.get(e['status_checked'], 0) + 1
for s, n in sorted(statuses.items(), key=lambda x: -x[1]):
    print(n, "|", s)
