# 1) citations.json vs INDEX (5-column parse)
idx = open('/work/workspace/library/INDEX.md').read()
data = json.load(open('/work/workspace/deliverable/citations.json'))
rows = {}
for line in idx.splitlines():
    m = re.match(r'^\|\s*`([^`]+)`\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*$', line)
    if m:
        rows[m.group(1)] = {"cite": m.group(3), "kind": m.group(4), "status": m.group(5)}
citable = {k for k in rows if not k.startswith('memo_bank/')}
errors, matched = [], set()
for e in data:
    f = e['library_file']
    if f not in rows: errors.append(f"{f}: NOT IN INDEX"); continue
    matched.add(f)
    if e['status_checked'] != rows[f]['status']:
        errors.append(f"{f}: status mismatch")
print("CITATIONS:", len(data), "entries | INDEX citable rows:", len(citable),
      "| missing:", sorted(citable - matched), "| errors:", errors if errors else "none")

# 2) final arithmetic line identity
print("ARITH: 0.10*0.05=%.4f  0.31*0.30=%.4f  (printed 0.005-0.093)" % (0.10*0.05, 0.31*0.30))

# 3) character scan
bad = []
for p in ['/work/workspace/deliverable/memo.md','/work/workspace/deliverable/QUESTIONS.md',
          '/work/workspace/deliverable/STATUS.md','/work/workspace/deliverable/citations.json']:
    t = open(p, encoding='utf-8').read()
    for i, ch in enumerate(t):
        o = ord(ch)
        if (0x3000 <= o <= 0x9FFF) or (0xFF00 <= o <= 0xFFEF) or o == 0xFFFD:
            bad.append((p, i, hex(o), unicodedata.name(ch, '?')))
print("CHAR SCAN:", bad if bad else "clean")
